package fpv.render;
import arc.*;import arc.graphics.*;import arc.graphics.g2d.*;import arc.mock.*;import arc.util.*;import mindustry.*;import mindustry.content.*;import mindustry.core.*;import mindustry.game.*;import mindustry.gen.*;import mindustry.world.*;import mindustry.world.blocks.production.*;import mindustry.world.blocks.power.*;import fpv.construction.*;import java.util.*;
public final class LiquidModelNativeTest {
 static int checks;static void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}static class Tex extends Texture{Tex(){super();width=height=64;}}
 static Block[] types(){return new Block[]{Blocks.conduit,Blocks.pulseConduit,Blocks.platedConduit,Blocks.liquidRouter,Blocks.liquidJunction,Blocks.bridgeConduit,Blocks.phaseConduit,Blocks.liquidContainer,Blocks.liquidTank,Blocks.mechanicalPump,Blocks.rotaryPump,Blocks.impulsePump,Blocks.thermalGenerator};}
 public static void main(String[] args)throws Exception{
  ArcNativesLoader.load();mindustry.graphics.CacheLayer.init();Core.app=new MockApplication();Core.files=new MockFiles();Core.settings=new MockSettings();Core.bundle=I18NBundle.createEmptyBundle();Core.audio=new MockAudio();Core.graphics=new MockGraphics();Core.gl=new MockGL20();Vars.headless=true;Vars.tree=new FileTree();Vars.content=new ContentLoader();Vars.content.createBaseContent();Vars.state=new GameState();Vars.net=new mindustry.net.Net(null);Groups.init();Vars.world=new World();Vars.world.tiles=new Tiles(128,96);Vars.world.setGenerating(true);Vars.world.tiles.fill();Vars.indexer=new mindustry.ai.BlockIndexer();Groups.resize(0,0,1024,768);Time.clear();Time.setDeltaProvider(()->1);Vars.content.init();Vars.state.set(GameState.State.playing);
  var pix=new Pixmap(32,32);pix.fill(0xa0a0a0ff);var region=new TextureAtlas.AtlasRegion(new Tex(),0,0,32,32);region.name="chemical-fixture";Core.atlas=new TextureAtlas(){@Override public PixmapRegion getPixmap(TextureAtlas.AtlasRegion a){return new PixmapRegion(pix);}};Core.atlas.addRegion("white",region);


  Block[] types=types();int[] sizes={1,1,1,1,1,1,1,2,3,1,2,3,2};check(!LiquidModelRenderer.supports(Blocks.cryofluidMixer)&&!LiquidModelRenderer.supports(Blocks.powerNode)&&!LiquidModelRenderer.supports(Blocks.reinforcedConduit),"explicit scope preserves prior models/Erekir");
  for(int i=0;i<types.length;i++){check(types[i].size==sizes[i],"installed footprint "+types[i].name);types[i].region=types[i].fullIcon=region;System.out.println("A2-16h native "+types[i].name+" size="+types[i].size+" liquidCapacity="+types[i].liquidCapacity+" physicalHeight="+fpv.net.HeadlessGeometry.heightFor(types[i])+" class="+types[i].buildType.get().getClass().getName());}
  for(var p:LiquidModelProfile.values())for(int mask=0;mask<16;mask++)for(int lod=0;lod<3;lod++){var g=LiquidModelGeometry.model(p,mask,lod);check(g==LiquidModelGeometry.model(p,mask,lod),"cached templates");int count=0;for(var a:new float[][]{g.body(),g.lining(),g.rotor(),g.lights()}){count+=a.length/8;check(a.length%24==0,"triangles");for(int i=0;i<a.length;i+=8){for(int j=0;j<8;j++)check(Float.isFinite(a[i+j]),"finite template");check(Math.abs(a[i])<=.501&&Math.abs(a[i+2])<=.501&&a[i+1]>=0&&a[i+1]<=1,"bounded mechanical envelope");}}check(count<1800,"bounded model complexity");}
  var renderer=new LiquidModelRenderer();var batch=new NativeAtlasMesh.Builder(false);long id=100;
  try{
   for(int floor:new int[]{0,1,3,4,5})for(int t=0;t<types.length;t++)for(int rotation=0;rotation<4;rotation++){
    var b=AdvancedLogisticsNativeTest.put(new LayerBuildingAdapter(null),id++,12+rotation*24,10+t*5,floor,types[t],rotation);b.enabled=true;b.efficiency=1;
    if(b instanceof Pump.PumpBuild pump){pump.totalProgress=19;pump.amount=1;pump.warmup=.7f;pump.liquidDrop=Liquids.water;}
    if(b instanceof ThermalGenerator.ThermalGeneratorBuild gen)gen.productionEfficiency=.7f;
    float clock=LiquidModelRenderer.clock(b);Time.time+=500;check(clock==LiquidModelRenderer.clock(b),"no fake global machinery clock");
    for(var liquid:new mindustry.type.Liquid[]{Liquids.water,Liquids.oil,Liquids.slag,Liquids.cryofluid,Liquids.neoplasm})for(float amount:new float[]{0,.5f,1}){
     if(b.liquids!=null){b.liquids.clear();b.liquids.set(liquid,b.block.liquidCapacity*amount);check(Math.abs(LiquidModelRenderer.fill(b)-amount)<.0001,"real stored fraction");check(LiquidModelRenderer.flow(b)==0,"unavailable native flow is not fabricated");}
     for(float distance:new float[]{0,900,10000}){var before=LogisticsModelNativeTest.state(b);float h=LiquidModelRenderer.visualHeight(b.block,fpv.net.HeadlessGeometry.heightFor(b.block)),base=floor*1.4f;batch.clear();check(renderer.render(b,batch,0,base,0,b.block.size,fpv.net.HeadlessGeometry.heightFor(b.block),distance),"actual XYZ/rotation/LOD");var vertices=LogisticsModelNativeTest.vertices(batch);for(int i=0;i<vertices.length;i+=9){for(int j=0;j<9;j++)check(Float.isFinite(vertices[i+j]),"finite stream");check(Math.abs(vertices[i])<=b.block.size*.501&&Math.abs(vertices[i+2])<=b.block.size*.501&&vertices[i+1]>=base-.001&&vertices[i+1]<=base+h+.01,"model stays within visual envelope and above support");}check(Arrays.equals(before,LogisticsModelNativeTest.state(b))&&clock==LiquidModelRenderer.clock(b),"read-only liquids/clocks/production/heat");}
    }
    if(b instanceof Pump.PumpBuild){b.enabled=false;check(LiquidModelRenderer.activity(b)==0,"disabled pump dark");}
   }
   check(renderer.entries()==13&&renderer.builds()==13&&renderer.bytes()<4_000_000,"bounded reusable material cache");
   var dry=AdvancedLogisticsNativeTest.put(new LayerBuildingAdapter(null),id++,20,80,3,Blocks.mechanicalPump,0);check(((Pump.PumpBuild)dry).liquidDrop==null&&LiquidModelRenderer.activity(dry)==0,"dry upper platform invents no pump production");
   Vars.world.setGenerating(false);
   for(int i=0;i<3;i++){var type=(Pump)types[9+i];int x=15+i*18,y=80,low=-(type.size-1)/2;for(int dx=0;dx<type.size;dx++)for(int dy=0;dy<type.size;dy++)Vars.world.tile(x+low+dx,y+low+dy).setFloor((mindustry.world.blocks.environment.Floor)Blocks.water);check(type.canPlaceOn(Vars.world.tile(x,y),Team.sharded,0),"native water-surface pump placement");Vars.world.tile(x,y).setBlock(type,Team.sharded,0);var pump=(Pump.PumpBuild)Vars.world.build(x,y);pump.onProximityUpdate();pump.efficiency=1;for(int n=0;n<120;n++){Time.delta=1;pump.updateTile();}check(pump.liquidDrop==Liquids.water&&pump.liquids.get(Liquids.water)>0&&pump.totalProgress>0,"native pump actually extracts and clocks advance");check(!type.canPlaceOn(Vars.world.tile(x,y-8),Team.sharded,0),"native dry terrain remains invalid");}
   var hot=(mindustry.world.blocks.environment.Floor)Blocks.hotrock;for(int dx=0;dx<2;dx++)for(int dy=0;dy<2;dy++)Vars.world.tile(100+dx,80+dy).setFloor(hot);check(Blocks.thermalGenerator.canPlaceOn(Vars.world.tile(100,80),Team.sharded,0),"native heat-floor placement");Vars.world.tile(100,80).setBlock(Blocks.thermalGenerator,Team.sharded,0);var thermal=(ThermalGenerator.ThermalGeneratorBuild)Vars.world.build(100,80);thermal.onProximityAdded();thermal.updateTile();check(thermal.productionEfficiency>0,"real native geothermal production");
   Vars.world.tile(70,85).setBlock(Blocks.conduit,Team.sharded,0);Vars.world.tile(71,85).setBlock(Blocks.conduit,Team.sharded,1);var corner=Vars.world.build(71,85);var separate=new LayerBuildingAdapter(null);AdvancedLogisticsNativeTest.put(separate,id++,72,85,3,Blocks.conduit,2);int mask=LiquidModelRenderer.openings(corner);check((mask&6)==6&&(mask&1)==0,"actual native corner follows XY neighbors, never other floors");Vars.world.build(70,85).team=Team.crux;check((LiquidModelRenderer.openings(corner)&4)==0,"foreign input excluded; only native rear fallback remains");separate.clear();
   System.out.println("LiquidModelNativeTest: "+checks+" installed scope/geometry/XYZ/rotations/liquid/empty/full/clock/read-only checks PASS; mock GL, no physical acceptance");
  }finally{renderer.clear();batch.dispose();pix.dispose();}
 }
}
